#!/usr/bin/env bash
# Docs : partie « Formulaires » en 7 chapitres — le tutoriel d'origine (2 938 lignes) restauré
# intégralement, découpé, et confronté au code actuel du projet ; remplace interface/formulaires.mdx.
# Prérequis : apply-docs-variables-env.sh.
# Usage (racine du repo) : bash apply-docs-formulaires.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/formulaires/du-html-a-react.mdx" 2>/dev/null | grep -qF "Le formulaire, du HTML à React"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Les variables d'environnement" "apps/web/content/docs/dev/configuration/variables-d-environnement.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-variables-env.sh"; exit 1; }
MODIFIED=("apps/web/src/features/docs/lib/docs.navigation.ts" "apps/web/src/mdx-components.tsx" "apps/web/content/docs/dev/api/trpc.mdx" "apps/web/content/docs/dev/donnees/modeliser-avec-prisma.mdx" "apps/web/content/docs/dev/index.mdx" "apps/web/content/docs/dev/interface/referencement.mdx" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx")
CREATED=("apps/web/content/docs/dev/formulaires/du-html-a-react.mdx" "apps/web/content/docs/dev/formulaires/react-hook-form.mdx" "apps/web/content/docs/dev/formulaires/use-action-state.mdx" "apps/web/content/docs/dev/formulaires/server-actions.mdx" "apps/web/content/docs/dev/formulaires/le-modele-hybride-face-au-reel.mdx" "apps/web/content/docs/dev/formulaires/les-pieges-du-modele-hybride.mdx" "apps/web/content/docs/dev/formulaires/choisir-son-modele.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/formulaires" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "Le formulaire, du HTML à React" "apps/web/content/docs/dev/formulaires/du-html-a-react.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/formulaires"
